<template>
<view class="page"><AchievementUnlockNotifier />
 <view v-if="!activeScene"><view class="hero"><text class="title">场景口语</text><text class="subtitle">选择生活场景，完成真实英文对话</text></view>
  <view class="section-heading"><text class="section-title">选择场景</text><text class="section-tip">每个场景 5 轮</text></view>
  <animated-loading v-if="loading" text="正在加载场景..."></animated-loading><view v-else class="scene-list"><view v-for="scene in scenes" :key="scene.id" class="scene-card" @click="startScene(scene)"><view class="scene-icon">{{scene.icon}}</view><view class="scene-info"><text class="scene-name">{{scene.name}}</text><text class="scene-desc">{{scene.description}}</text></view><text class="scene-action">开始 ›</text></view></view>
 </view>
 <view v-else-if="!completed" class="practice-page"><view class="practice-head"><view><text class="scene-kicker">{{activeScene.icon}} {{activeScene.name}}</text><text class="round">第 {{currentIndex+1}} / {{rounds.length}} 轮</text></view><text class="exit" @click="exitPractice">退出</text></view><view class="progress"><view class="progress-fill" :style="{width:progress+'%'}"></view></view>
  <scroll-view class="chat-list" scroll-y :scroll-into-view="chatAnchor"><view v-for="(message,index) in chatMessages" :key="index" :id="'chat-'+index" class="message-row" :class="message.role"><view v-if="message.role==='assistant'" class="chat-avatar">🤖</view><view class="message-body"><text class="speaker">{{message.role==='assistant'?'对方':'我'}}</text><view class="bubble"><text class="bubble-en">{{message.text}}</text><text v-if="message.chinese" class="bubble-zh">{{message.chinese}}</text><text v-if="message.voice" class="voice-mark">🎤 语音回答 · {{message.score}}分</text></view><text v-if="message.role==='assistant'" class="play-link" @click="playText(message.text)">🔊 播放</text></view><view v-if="message.role==='user'" class="chat-avatar user-avatar">我</view></view><view :id="chatAnchor"></view></scroll-view>
  <view class="bottom-dock"><view class="reply-guide"><text class="task-label">本轮表达任务</text><text class="task-zh">{{currentRound.taskZh}}</text><text class="answer-hint">参考：{{currentRound.answer}}</text></view><view v-if="hasResult" class="result" :class="passed?'passed':'failed'"><view class="result-top"><text>{{passed?'回答通过，即将进入下一轮':'暂未通过'}}</text><text class="score">{{score}}分</text></view><text class="feedback">{{feedback}}</text></view><view v-if="!passed" class="composer"><view class="composer-row"><view class="mic-button" :class="{recording:isRecording,evaluating}" @click="toggleRecord">{{evaluating?'…':isRecording?'■':'🎤'}}</view><input v-model="inputText" class="chat-input" :disabled="isRecording||evaluating" confirm-type="send" placeholder="输入英文回复" @confirm="sendTextReply"/><button class="send-button" :disabled="!inputText.trim()||isRecording||evaluating" @click="sendTextReply">发送</button></view><text v-if="isRecording" class="record-tip">正在录音 {{recordSeconds}} 秒，点击红色按钮结束</text><text v-else class="composer-tip">可以输入英文，也可以点击麦克风语音回答</text></view></view> </view> <view v-else class="complete-card"><view class="complete-icon">🎉</view><text class="complete-title">场景对话完成</text><text class="complete-scene">{{activeScene.icon}} {{activeScene.name}}</text><view class="summary"><view><text>{{rounds.length}}</text><text>完成轮次</text></view><view><text>{{averageScore}}</text><text>平均得分</text></view></view><text class="suggestion">{{summarySuggestion}}</text><button class="primary" @click="backToScenes">继续选择场景</button><button class="secondary" @click="goBack">完成并返回</button></view>
</view>
</template>
<script>
import{request,transcribeSpeech,saveDialogueHistory}from'@/utils/api.js';import{getAudioSettings}from'@/utils/learning-settings.js';import{playTts,clearTtsQueue}from'@/utils/tts-player.js';
import { playAnswerFeedback } from '@/utils/answer-feedback.js';
import { isFirstLoad } from '@/utils/first-load.js';
import { normalizeEnglishSentence, englishWords } from '@/utils/answer-normalization.js';
const PASS_SCORE=80;
const DEFAULT_SCENES=[{id:1,icon:'🍽️',name:'餐厅点餐',description:'练习点餐、饮品和结账表达'},{id:2,icon:'🗺️',name:'问路指路',description:'练习询问地点和确认路线'},{id:3,icon:'🛒',name:'购物消费',description:'练习询价、试穿和付款表达'},{id:4,icon:'💼',name:'职场寒暄',description:'练习问候、近况和工作交流'}];
const ROUNDS={
'餐厅点餐':[{prompt:'Good evening. Are you ready to order?',promptZh:'晚上好，您准备好点餐了吗？',taskZh:'是的，我想要一份牛排',answer:'Yes, I would like a steak, please.'},{prompt:'What would you like to drink?',promptZh:'您想喝点什么？',taskZh:'请给我一杯橙汁',answer:'I would like a glass of orange juice, please.'},{prompt:'Would you like anything else?',promptZh:'您还需要别的吗？',taskZh:'不用了，请给我账单',answer:'No, thank you. Could I have the bill, please?'}],
'问路指路':[{prompt:'Hello. Can I help you?',promptZh:'你好，需要帮助吗？',taskZh:'请问最近的地铁站在哪里',answer:'Excuse me, where is the nearest subway station?'},{prompt:'Go straight and turn left at the traffic lights.',promptZh:'直走，在红绿灯处左转。',taskZh:'询问走路需要多长时间',answer:'How long does it take to walk there?'},{prompt:'It takes about ten minutes.',promptZh:'大约需要十分钟。',taskZh:'感谢对方的帮助',answer:'Thank you very much for your help.'}],
'购物消费':[{prompt:'Welcome. What are you looking for today?',promptZh:'欢迎光临，您今天想买什么？',taskZh:'我在找一件蓝色衬衫',answer:'I am looking for a blue shirt.'},{prompt:'Would you like to try this one?',promptZh:'您想试试这件吗？',taskZh:'询问是否有大一号',answer:'Do you have this in a larger size?'},{prompt:'Yes, here you are.',promptZh:'有的，给您。',taskZh:'表示决定购买',answer:'It fits well. I will take it.'}],
'职场寒暄':[{prompt:'Good morning. How was your weekend?',promptZh:'早上好，周末过得怎么样？',taskZh:'周末很好，并感谢询问',answer:'It was great, thank you for asking.'},{prompt:'Are you busy with the new project?',promptZh:'你最近在忙新项目吗？',taskZh:'表示正在准备下午的会议',answer:'Yes, I am preparing for the meeting this afternoon.'},{prompt:'Let me know if you need any help.',promptZh:'如果需要帮助请告诉我。',taskZh:'感谢并表示有需要会告知',answer:'Thank you. I will let you know if I need help.'}]};
const EXTRA_ROUNDS={
'餐厅点餐':[{prompt:'How would you like your steak?',promptZh:'您的牛排想要几分熟？',taskZh:'我要七分熟',answer:'I would like it medium well, please.'},{prompt:'Did you enjoy your meal?',promptZh:'您用餐还满意吗？',taskZh:'食物很好吃，表示感谢',answer:'Yes, the food was delicious. Thank you.'}],
'问路指路':[{prompt:'You will see the station next to the bank.',promptZh:'你会在银行旁边看到地铁站。',taskZh:'确认地铁站在银行旁边',answer:'Is the subway station next to the bank?'},{prompt:'Yes, you cannot miss it.',promptZh:'是的，很容易找到。',taskZh:'礼貌告别',answer:'I understand. Have a nice day.'}],
'购物消费':[{prompt:'Would you like to pay by cash or card?',promptZh:'您想用现金还是刷卡？',taskZh:'我想刷卡付款',answer:'I would like to pay by card.'},{prompt:'Here is your receipt. Have a nice day.',promptZh:'这是您的收据，祝您愉快。',taskZh:'感谢并礼貌告别',answer:'Thank you. Have a nice day too.'}],
'职场寒暄':[{prompt:'What do you think about the new project?',promptZh:'你觉得这个新项目怎么样？',taskZh:'我认为这个项目很有挑战性',answer:'I think the project is very challenging.'},{prompt:'Shall we discuss it after lunch?',promptZh:'我们午饭后讨论一下好吗？',taskZh:'同意并约在下午两点',answer:'Sure. Let us meet at two this afternoon.'}]};export default{data(){const firstLoad=isFirstLoad('pages/dialogue/index');return{firstLoad,loading:firstLoad,scenes:[],activeScene:null,rounds:[],currentIndex:0,isRecording:false,evaluating:false,recorder:null,recordStartedAt:0,recordTimer:null,autoTimer:null,recordSeconds:0,hasResult:false,passed:false,score:0,feedback:'',scores:[],completed:false,audio:null,voiceType:1,autoPlay:true,leaving:false,startedAt:0,advanceTimer:null,inputText:'',chatMessages:[],chatAnchor:''}},computed:{currentRound(){return this.rounds[this.currentIndex]||{}},progress(){return this.rounds.length?(this.currentIndex+(this.passed?1:0))/this.rounds.length*100:0},averageScore(){return this.scores.length?Math.round(this.scores.reduce((a,b)=>a+b,0)/this.scores.length):0},summarySuggestion(){return this.averageScore>=90?'表达自然流畅，可以尝试更自由的表达。':this.averageScore>=80?'整体表现很好，继续注意句子节奏和语调。':'已完成练习，建议重听原句并加强易错词发音。'}},async onLoad(){const s=await getAudioSettings();this.voiceType=s.voiceType;this.autoPlay=s.autoPlay!==false;this.initRecorder();this.loadScenes()},onUnload(){clearTtsQueue();this.leaving=true;this.clearTimers();if(this.isRecording&&this.recorder)this.recorder.stop();if(this.audio)this.audio.destroy()},methods:{async loadScenes(){if(this.firstLoad){this.loading=true;this.firstLoad=false}try{const rows=await request('/scene/list');this.scenes=rows?.length?rows:DEFAULT_SCENES}catch(_){this.scenes=DEFAULT_SCENES}finally{this.loading=false}},startScene(scene){this.activeScene=scene;this.rounds=[...(ROUNDS[scene.name]||ROUNDS['餐厅点餐']),...(EXTRA_ROUNDS[scene.name]||[])];this.currentIndex=0;this.scores=[];this.completed=false;this.startedAt=Date.now();this.chatMessages=[];this.addAssistantMessage();this.resetRound();if(this.autoPlay)this.playText(this.currentRound.prompt)},resetRound(){this.hasResult=false;this.passed=false;this.score=0;this.feedback='';this.recordSeconds=0;this.inputText=''} ,addAssistantMessage(){const r=this.currentRound;this.chatMessages.push({role:'assistant',text:r.prompt,chinese:r.promptZh});this.scrollChat()},scrollChat(){this.$nextTick(()=>{this.chatAnchor='chat-'+Math.max(0,this.chatMessages.length-1)})},normalizeText(value){return normalizeEnglishSentence(value)},textScoreOf(input,target){const a=this.normalizeText(input),b=this.normalizeText(target);if(!a)return 0;if(a===b)return 100;const aw=englishWords(a),bw=englishWords(b),targetWords=[...new Set(bw.filter(word=>word.length>1))],inputWords=new Set(aw);const common=targetWords.filter(word=>inputWords.has(word)).length;const coverage=common/Math.max(1,targetWords.length);const contains=a.includes(b)||b.includes(a);return Math.min(99,Math.round(Math.max(coverage*100,contains?85:0)))},sendTextReply(){const value=this.inputText.trim();if(!value||this.evaluating||this.isRecording)return;const result=this.textScoreOf(value,this.currentRound.answer);this.chatMessages.push({role:'user',text:value});this.inputText='';this.score=result;this.hasResult=true;this.passed=result>=PASS_SCORE;playAnswerFeedback(this.passed);this.feedback=this.passed?'表达符合本轮任务。':'表达与本轮任务不够匹配，请参考提示重新回答。';this.scrollChat();this.playText(value,this.passed?()=>this.scheduleAdvance():null)},initRecorder(){this.recorder=uni.getRecorderManager();this.recorder.onStop(r=>{this.isRecording=false;this.clearTimers();if(this.leaving)return;if(Date.now()-this.recordStartedAt<1000)return uni.showToast({title:'录音太短，请说完整句话',icon:'none'});if(!r.tempFilePath)return uni.showToast({title:'未获取到录音，请重试',icon:'none'});this.transcribe(r.tempFilePath)});this.recorder.onError(()=>{this.isRecording=false;this.evaluating=false;this.clearTimers();uni.showToast({title:'录音失败，请检查麦克风权限',icon:'none'})})},clearTimers(){if(this.recordTimer){clearInterval(this.recordTimer);this.recordTimer=null}if(this.autoTimer){clearTimeout(this.autoTimer);this.autoTimer=null}if(this.advanceTimer){clearTimeout(this.advanceTimer);this.advanceTimer=null}},ensurePermission(){return new Promise(resolve=>uni.getSetting({success:s=>{const v=s.authSetting['scope.record'];if(v===true)return resolve(true);if(v===false)return uni.showModal({title:'需要麦克风权限',content:'请允许使用麦克风后再练习。',confirmText:'去设置',success:r=>r.confirm?uni.openSetting({success:x=>resolve(x.authSetting['scope.record']===true),fail:()=>resolve(false)}):resolve(false)});uni.authorize({scope:'scope.record',success:()=>resolve(true),fail:()=>resolve(false)})},fail:()=>resolve(false)}))},async toggleRecord(){if(this.evaluating)return;if(this.isRecording){this.recorder.stop();return}if(!await this.ensurePermission())return;this.resetRound();this.isRecording=true;this.recordStartedAt=Date.now();this.recorder.start({duration:20000,sampleRate:16000,numberOfChannels:1,encodeBitRate:48000,format:'mp3'});this.recordTimer=setInterval(()=>this.recordSeconds=Math.floor((Date.now()-this.recordStartedAt)/1000),250);this.autoTimer=setTimeout(()=>{if(this.isRecording)this.recorder.stop()},20000)},transcribe(path){this.evaluating=true;uni.getFileSystemManager().readFile({filePath:path,encoding:'base64',success:async f=>{try{const result=await transcribeSpeech(f.data,'mp3');this.inputText=String(result?.text||'').trim();if(this.inputText)uni.showToast({title:'已转换为文字，请确认后发送',icon:'none'});else uni.showToast({title:'没有识别到英文，请重试',icon:'none'})}catch(e){uni.showToast({title:e.message||'语音识别失败，请重试',icon:'none'})}finally{this.evaluating=false}},fail:()=>{this.evaluating=false;uni.showToast({title:'读取录音失败',icon:'none'})}})},scheduleAdvance(){if(this.advanceTimer)clearTimeout(this.advanceTimer);this.advanceTimer=setTimeout(()=>this.nextRound(),1200)},nextRound(){if(!this.passed)return;this.scores.push(this.score);if(this.currentIndex+1<this.rounds.length){this.currentIndex++;this.resetRound();this.addAssistantMessage();if(this.autoPlay)this.playText(this.currentRound.prompt)}else this.finishScene()},async finishScene(){this.completed=true;const messages=this.chatMessages.map(message=>({...message}));try{await saveDialogueHistory({scene_name:this.activeScene.name,scene_icon:this.activeScene.icon,messages,average_score:this.averageScore,duration:Math.max(1,Math.round((Date.now()-this.startedAt)/60000))})}catch(_){uni.showToast({title:'成绩暂未同步，已保留结果',icon:'none'})}},playText(text,onEnded=null){playTts(text,3).then(()=>{if(onEnded)onEnded()}).catch(error=>{console.error('对话音频播放失败:',error);uni.showToast({title:error?.message||'音频播放失败',icon:'none'});if(onEnded)onEnded()})},exitPractice(){uni.showModal({title:'退出当前场景？',content:'未完成的进度不会保存。',success:r=>{if(r.confirm)this.backToScenes()}})},backToScenes(){clearTtsQueue();this.clearTimers();this.activeScene=null;this.completed=false;this.resetRound()},goBack(){uni.navigateBack()}}}
</script>
<style>
.page{box-sizing:border-box;min-height:100vh;padding:24rpx 22rpx 55rpx;background:linear-gradient(180deg,#eef5f6 0,#f7f5f0 420rpx)}.hero{padding:28rpx;border-radius:26rpx;background:#1f3a5f;color:#fff;box-shadow:0 13rpx 30rpx rgba(31,58,95,.18)}.title{display:block;font-size:40rpx;font-weight:800}.subtitle{display:block;margin-top:7rpx;font-size:22rpx;color:rgba(255,255,255,.72)}.section-heading{display:flex;align-items:center;justify-content:space-between;margin:31rpx 5rpx 15rpx}.section-title{font-size:32rpx;font-weight:800;color:#213f61}.section-tip{font-size:21rpx;color:#8e9aa4}.scene-list{display:flex;flex-direction:column;gap:13rpx}.scene-card{display:flex;align-items:center;padding:23rpx 21rpx;border-radius:22rpx;background:#fff;box-shadow:0 7rpx 21rpx rgba(35,63,87,.07)}.scene-icon{display:flex;align-items:center;justify-content:center;width:68rpx;height:68rpx;border-radius:19rpx;background:#e6f5f2;font-size:33rpx}.scene-info{flex:1;margin-left:17rpx}.scene-name{display:block;font-size:28rpx;font-weight:800;color:#294866}.scene-desc{display:block;margin-top:5rpx;font-size:22rpx;color:#8d99a3}.scene-action{font-size:22rpx;font-weight:700;color:#0d9488}.empty{padding:100rpx 20rpx;text-align:center;color:#8b969f}.practice-head{display:flex;align-items:center;justify-content:space-between}.scene-kicker{display:block;font-size:32rpx;font-weight:800;color:#1f3a5f}.round{display:block;margin-top:5rpx;font-size:22rpx;color:#84919c}.exit{font-size:23rpx;color:#8e98a1}.progress{height:10rpx;margin:20rpx 0;border-radius:10rpx;background:#dfe7e9;overflow:hidden}.progress-fill{height:100%;background:#0d9488}.conversation-card,.task-card{margin-top:18rpx;padding:25rpx;border-radius:23rpx;background:#fff;box-shadow:0 7rpx 22rpx rgba(35,63,87,.08)}.speaker-row{display:flex;align-items:center;gap:10rpx;font-size:22rpx;color:#7d8994}.avatar{display:flex;align-items:center;justify-content:center;width:50rpx;height:50rpx;border-radius:15rpx;background:#edf3f7}.prompt-en{display:block;margin-top:20rpx;font-size:32rpx;font-weight:800;line-height:1.45;color:#294866}.prompt-zh{display:block;margin-top:8rpx;font-size:23rpx;color:#83909a}.play-button{display:inline-flex;margin-top:21rpx;padding:13rpx 20rpx;border-radius:28rpx;background:#e6f6f3;color:#0d9488;font-size:22rpx}.task-label{display:block;font-size:22rpx;font-weight:700;color:#0d9488}.task-zh{display:block;margin-top:13rpx;font-size:28rpx;font-weight:800;color:#294866}.answer-hint{display:block;margin-top:13rpx;padding:16rpx;border-radius:14rpx;background:#f4f7f8;font-size:23rpx;line-height:1.5;color:#687986}.record-button{display:flex;justify-content:center;margin-top:22rpx;padding:22rpx;border-radius:17rpx;background:#1f3a5f;color:#fff;font-size:27rpx;font-weight:800}.record-button.recording{background:#d54d4d}.record-button.evaluating{background:#718292}.record-tip{display:block;margin-top:10rpx;text-align:center;font-size:21rpx;color:#d35454}.result{margin-top:18rpx;padding:18rpx;border-radius:15rpx}.result.passed{background:#edf9f5;color:#0d8d80}.result.failed{background:#fff3f1;color:#c95048}.result-top{display:flex;justify-content:space-between;font-size:25rpx;font-weight:800}.score{font-size:31rpx}.feedback{display:block;margin-top:7rpx;font-size:22rpx;color:#677985}.next-button,.primary,.secondary{margin-top:20rpx;border:0;border-radius:16rpx;background:#0d9488;color:#fff;font-size:27rpx}.secondary{background:#edf2f5;color:#294866}.complete-card{margin-top:80rpx;padding:45rpx 28rpx;border-radius:25rpx;background:#fff;text-align:center}.complete-icon{font-size:72rpx}.complete-title{display:block;margin-top:12rpx;font-size:40rpx;font-weight:800;color:#1f3a5f}.complete-scene{display:block;margin-top:8rpx;font-size:25rpx;color:#788793}.summary{display:flex;margin-top:27rpx;padding:20rpx;border-radius:17rpx;background:#f3f7f8}.summary view{flex:1}.summary text:first-child{display:block;font-size:35rpx;font-weight:800;color:#0d9488}.summary text:last-child{display:block;font-size: